#include "dk1/ppu_layout.h"
static bool reg(const Dk1PpuPreset*p,uint16_t a,uint8_t*v){return dk1_ppu_preset_register(p,a,v);}
bool dk1_ppu_bg_layout(const Dk1PpuPreset*p,uint8_t bg,Dk1PpuBgLayout*l){uint8_t modev=0,sc=0,nba=0,tm=0;uint8_t size;if(!p||!l||bg<1||bg>4||!reg(p,0x2105,&modev)||!reg(p,(uint16_t)(0x2106u+bg),&sc)||!reg(p,bg<=2?0x210B:0x210C,&nba)||!reg(p,0x212C,&tm))return false;l->bg=bg;l->mode=modev&7u;l->screen_base_word=(uint16_t)((sc&0xFCu)<<8u);size=sc&3u;l->tilemap_width=(size&1u)?64u:32u;l->tilemap_height=(size&2u)?64u:32u;l->large_tiles=(modev&(uint8_t)(0x08u<<bg))!=0;l->main_enabled=(tm&(1u<<(bg-1u)))!=0;if(bg==1)l->character_base_word=(uint16_t)((nba&0x0Fu)*0x1000u);else if(bg==2)l->character_base_word=(uint16_t)(((nba>>4u)&0x0Fu)*0x1000u);else if(bg==3)l->character_base_word=(uint16_t)((nba&0x0Fu)*0x1000u);else l->character_base_word=(uint16_t)(((nba>>4u)&0x0Fu)*0x1000u);l->bits_per_pixel=0;if(l->mode==0)l->bits_per_pixel=2;else if(l->mode==1)l->bits_per_pixel=(bg<=2)?4:2;else if(l->mode==2)l->bits_per_pixel=(bg<=2)?4:0;else if(l->mode==3)l->bits_per_pixel=bg==1?8:(bg==2?4:0);else if(l->mode==4)l->bits_per_pixel=bg==1?8:(bg==2?2:0);else if(l->mode==5)l->bits_per_pixel=bg<=2?4:0;else if(l->mode==6)l->bits_per_pixel=bg==1?4:0;else if(l->mode==7)l->bits_per_pixel=bg==1?8:0;return l->bits_per_pixel!=0;}
